255: {
256:   if (is_completed())
257:     return true;
258: 
259:   Impl& impl = m_conn.get_base_impl();
260: 
261:   const bytes& buffer = m_bufs.get_buffer(m_currentBufferIdx);
262:   byte* data =buffer.begin() + m_currentBufferOffset;
263:   size_t buffer_size = buffer.size() - m_currentBufferOffset;
264: 
265:   m_currentBufferOffset += detail::recv_some(impl.m_sock, data, buffer_size, 0);
266: 
267:   if (m_currentBufferOffset == buffer.size())
268:   {
269:     ++m_currentBufferIdx;
