629: Socket connect(const char *host_name, unsigned short port, uint64_t cn_timeout_usec)
630: {
631:   Socket socket = NULL_SOCKET;
632:   addrinfo* host_list = NULL;
633:   auto deadline = system_clock::now() + microseconds(cn_timeout_usec);
634: 
635:   // Resolve host name.
636:   // TODO: Configurable number of attempts
637:   int attempts = 2;
638:   while (!host_list)
639:   {
640:     attempts--;
641:     try
642:     {
643:       /*
644:         The DNS async resolution is not supported on all platforms.
645:         Therefore, we will do the blocking call and measure the time
646:       */
647:       host_list = detail::addrinfo_from_string(host_name, port);
648:       if (cn_timeout_usec > 0 && system_clock::now() >= deadline)
649:       {
650:         throw Connect_timeout_error(cn_timeout_usec / 1000);
651:       }
652:     }
653:     catch (Error& e)
654:     {
655:       if(e != errc::resource_unavailable_try_again || attempts <= 0)
656:         throw;
657:     }
658:   }
659: 
660:   struct AddrInfoGuard
661:   {
662:     addrinfo* list;
663:     ~AddrInfoGuard() NOEXCEPT { freeaddrinfo(list); }
664:   }
665:   guard = { host_list };
666: 
667:   // Connect to host.
668:   int connect_result = SOCKET_ERROR;
669:   addrinfo* host = host_list;
670: 
671:   while (connect_result != 0 && host)
672:   {
673:     try
674:     {
675:       socket = detail::socket(true, host);
676: 
677:       connect_result = ::connect(socket, host->ai_addr, static_cast<int>(host->ai_addrlen));
678: 
679:       if (connect_result != 0)
680:       {
681:       #ifdef _WIN32
682:         if (connect_result == SOCKET_ERROR && WSAGetLastError() == WSAEWOULDBLOCK)
683:       #else
684:         if (connect_result == SOCKET_ERROR && errno == EINPROGRESS)
685:       #endif
686:         {
687: 
688:           int select_result = 0;
689: 
690:           do{
691: 
692:             auto timeout = duration_cast<microseconds>(
693:               deadline - system_clock::now()
694:             ).count();
695: 
696:             select_result = poll_one(
697:                               socket, POLL_MODE_CONNECT, true,
698:                               0 == cn_timeout_usec ? 0 : timeout > 0 ? timeout : 1
699:                                                                     );
700:           // Note: if poll_one() returns 0 then, according to POSIX specs:
701:           // A value of 0 indicates that the call timed out and no file descriptors have been selected
702:           // Due to a bug on WSApool, it may return 0 even if no timeout occur..
703:           // So we will check if timeout occurs and try again if not
704: 
705:           } while ((select_result == 0) &&
706:                    ((cn_timeout_usec == 0) ||
707:                     (std::chrono::system_clock::now() < deadline)
708:                     )
709:                    );
710: 
711:           if ((cn_timeout_usec > 0) &&
712:               (std::chrono::system_clock::now() >= deadline))
713:           {
714:             // Throw the error in milliseconds, which we did not adjust.
715:             // Otherwise the user will be confused why the timeout
716:             // in the error message is smaller than defined
717:             // (original timeout minus DNS resolution time)
718:             throw Connect_timeout_error(cn_timeout_usec / 1000);
719:           }
720: 
721:           if (select_result < 0)
722:             throw_socket_error();
723:           else
724:             check_socket_error(socket);
725: 
726:           connect_result = 0;
727:         }
728:         else
729:         {
730:           throw_socket_error();
731:         }
732:       }
733:     }
734:     catch (Connect_timeout_error&)
735:     {
736:       close(socket);
737:       throw;
738:     }
739:     catch (...)
740:     {
741:       close(socket);
742: 
743:       host = host->ai_next;
744:       if (!host)
745:         throw;
746:     }
747:   }
748: 
749:   return socket;
750: }
